CREATE OR REPLACE FUNCTION public.assign_verified_master() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN IF NEW.email_confirmed_at IS NOT NULL AND lower(NEW.email)='swiftdeliveryexpress4@gmail.com' THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'master_admin') ON CONFLICT(role) DO UPDATE SET user_id=EXCLUDED.user_id; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.is_master_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN auth.users u ON u.id=r.user_id WHERE r.user_id=auth.uid() AND r.role='master_admin' AND lower(u.email)='swiftdeliveryexpress4@gmail.com' AND u.email_confirmed_at IS NOT NULL) $$;
REVOKE ALL ON FUNCTION public.is_master_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_master_admin() TO authenticated,service_role;
ALTER TABLE public.master_admin_reservation ALTER COLUMN email SET DEFAULT 'swiftdeliveryexpress4@gmail.com';